{
  "identity": {
    "name": "MicroTech Systems",
    "location": "Boise / Garden City, Idaho (125 E 50th Street, Boise/Garden City, ID 83714)",
    "claims": [
      {
        "statement": "MicroTech Systems lists its address in the footer as 125 E 50th Street, Boise, ID 83714 and operating hours as 9AM - 5PM Monday-Friday.",
        "label": "fact",
        "sourceUrl": "https://www.microtechboise.com/",
        "quote": "Microtech Systems 125 E 50th Street , Boise, ID 83714 | 9AM - 5PM Monday-Friday"
      },
      {
        "statement": "The Contact Us page lists the street address at 125 E 50th St in Garden City, ID 83714.",
        "label": "fact",
        "sourceUrl": "https://www.microtechboise.com/contact-us",
        "quote": "125 E 50th St, Garden City, ID 83714"
      },
      {
        "statement": "MicroTech Systems states that it started as a family business in 1970.",
        "label": "fact",
        "sourceUrl": "https://www.microtechboise.com/en/about-microtech",
        "quote": "We started as a family business in 1970"
      }
    ]
  },
  "industry": {
    "industry": "Managed IT Services Provider (MSP) and Cybersecurity Services",
    "activities": [
      "Managed IT services and ongoing IT support",
      "24x7 remote network monitoring",
      "Cybersecurity services, antivirus, and encrypted cloud backups",
      "Cloud IT solutions and Microsoft 365 migration",
      "Windows server management",
      "AI-powered internal security solutions and custom AI security integration"
    ],
    "claims": [
      {
        "statement": "MicroTech Systems operates as a Managed IT Service Provider in Boise offering ongoing Managed IT Services.",
        "label": "fact",
        "sourceUrl": "https://www.microtechboise.com/",
        "quote": "As your dedicated IT support company in Boise, we provide ongoing Managed IT Services to ensure your business runs consistently and efficiently."
      },
      {
        "statement": "The company provides IT support, proactive network monitoring, cybersecurity, cloud solutions, and Microsoft 365 migration.",
        "label": "fact",
        "sourceUrl": "https://www.microtechboise.com/",
        "quote": "MicroTech provides ongoing IT support, proactive network monitoring, cybersecurity, cloud solutions, and Microsoft 365 migration to ensure your business runs efficiently."
      },
      {
        "statement": "MicroTech Systems sells AI-powered internal IT security solutions and custom AI solutions integration to other businesses.",
        "label": "fact",
        "sourceUrl": "https://www.microtechboise.com/ai-internal-security-solutions",
        "quote": "Safeguard your organization from insider threats, unauthorized access, and hidden vulnerabilities with AI-powered internal IT security solutions from MicroTech Systems."
      },
      {
        "statement": "MicroTech Systems is a B2B technology and IT services provider rather than a home-service contractor in HVAC, plumbing, or electrical.",
        "label": "inference",
        "sourceUrl": "https://www.microtechboise.com/",
        "quote": null
      }
    ]
  },
  "publicInformation": {
    "officialWebsite": "https://www.microtechboise.com/",
    "claims": [
      {
        "statement": "The company claims over 50 years of experience serving small and midsize businesses in the Boise area.",
        "label": "fact",
        "sourceUrl": "https://www.microtechboise.com/",
        "quote": "With over 50 years of experience serving Boise small and midsize businesses, we deliver solutions that minimize downtime and maximize productivity."
      },
      {
        "statement": "MicroTech Systems markets a 5-Star Promise that discounts the client's bill if predefined service criteria are not met.",
        "label": "fact",
        "sourceUrl": "https://www.microtechboise.com/en/about-microtech",
        "quote": "And, if we don’t meet it, we discount the bill."
      },
      {
        "statement": "The homepage contains multiple blocks of unreplaced placeholder text ('Lorem ipsum dolor sit amet').",
        "label": "fact",
        "sourceUrl": "https://www.microtechboise.com/",
        "quote": "Lorem ipsum dolor sit amet, consectetur adipiscing elit. Id egestas nunc, habitasse ipsum."
      }
    ]
  },
  "licensing": {
    "claims": [
      {
        "statement": "The About Us page mentions that industry certifications are near-standard practice, and the AI security page refers to 'certified engineers', without listing specific license or registration numbers.",
        "label": "fact",
        "sourceUrl": "https://www.microtechboise.com/ai-internal-security-solutions",
        "quote": "Our certified engineers install, configure, and optimize AI security modules with minimal disruption."
      }
    ],
    "limitations": "No state contractor license numbers, corporate registration numbers, or specific vendor certification IDs are stated on the pages read."
  },
  "existingSoftware": [
    {
      "product": "TechCare™",
      "purpose": "Proprietary IT support service framework for network monitoring, malware protection, automated backups, and Windows server management",
      "evidence": {
        "statement": "MicroTech describes TechCare™ as its proprietary IT support service in Boise.",
        "label": "fact",
        "sourceUrl": "https://www.microtechboise.com/",
        "quote": "TechCare™ is the proprietary IT support service offered by MicroTech in Boise."
      }
    },
    {
      "product": "AI-driven monitoring, automated incident response, and security integration tools",
      "purpose": "Internal threat detection, alert prioritization, and automated security response",
      "evidence": {
        "statement": "MicroTech states that its AI systems integrate with security infrastructure to automate alerts, responses, and containment steps.",
        "label": "fact",
        "sourceUrl": "https://www.microtechboise.com/ai-internal-security-solutions",
        "quote": "Our AI systems integrate with your security infrastructure to automate alerts, responses, and containment steps, reducing human workload and downtime."
      }
    },
    {
      "product": "HubSpot CMS / Marketing & Forms Platform",
      "purpose": "Website hosting, content management, forms, and call-to-action tracking",
      "evidence": {
        "statement": "The website loads scripts and references hosts such as app-na2.hubspot.com, cp-na2.hubspot.com, and _hcms/forms/v2.js, which indicate usage of HubSpot.",
        "label": "hypothesis",
        "sourceUrl": null,
        "quote": null
      }
    },
    {
      "product": "Google Tag Manager",
      "purpose": "Website tag and analytics management",
      "evidence": {
        "statement": "Pages on the website embed frames from googletagmanager.com, indicating use of Google Tag Manager.",
        "label": "hypothesis",
        "sourceUrl": null,
        "quote": null
      }
    }
  ],
  "opportunityEvidence": [
    {
      "statement": "The homepage contains a section with unedited placeholder text ('What this service helps to do. Lorem ipsum dolor sit amet').",
      "label": "fact",
      "sourceUrl": "https://www.microtechboise.com/",
      "quote": "What this service helps to do. Lorem ipsum dolor sit amet"
    },
    {
      "statement": "The Submit a Ticket page displays contact details and headings to create a ticket, though no HTML form target was detected directly in the static DOM.",
      "label": "inference",
      "sourceUrl": "https://www.microtechboise.com/submit_ticket",
      "quote": null
    }
  ],
  "problems": [
    {
      "problem": "Website quality control gap evidenced by unreplaced 'Lorem ipsum' placeholder copy on the live homepage.",
      "label": "fact",
      "basis": "Directly observable on https://www.microtechboise.com/ under the heading 'What this service helps to do.'"
    }
  ],
  "existingSolutions": [
    {
      "solution": "Website CMS editing and internal MSP automation/ticketing tools",
      "addresses": "Updating website placeholder copy and managing IT support ticket triage and AI monitoring",
      "alreadyOwned": true
    }
  ],
  "forgexSolutions": [],
  "feasibility": {
    "rating": "not applicable",
    "explanation": "No ForgeX solution is recommended because MicroTech Systems is a Managed IT Services Provider outside ForgeX's home-service contractor segment and already builds and sells its own IT and AI automation services."
  },
  "aiDelivery": {
    "rating": "not applicable",
    "explanation": "No ForgeX solution is recommended."
  },
  "humanReview": [],
  "risks": [
    {
      "type": "operational",
      "description": "Pitching basic automation services to an established Managed IT Services Provider that already markets custom AI security integrations and automated IT monitoring is misaligned with ForgeX's positioning."
    }
  ],
  "commercial": {
    "supportable": false,
    "value": null,
    "implementationCost": null,
    "assumptions": []
  },
  "contacts": {
    "decisionMakerRoles": [
      "Owner / President",
      "Director of Operations / Service Manager"
    ],
    "people": [],
    "channels": [
      {
        "kind": "email",
        "value": "[redacted]",
        "sourceUrl": "https://www.microtechboise.com/contact-us"
      }
    ]
  },
  "discovery": {
    "questions": [],
    "outreachSubject": "",
    "outreachBody": ""
  },
  "evidence": {
    "sourcesUsed": [
      {
        "url": "https://www.microtechboise.com/",
        "usedFor": "Business identity, location, core IT/MSP service offerings, TechCare™ description, and homepage content check"
      },
      {
        "url": "https://www.microtechboise.com/en/about-microtech",
        "usedFor": "Company history (founded 1970 as a family business) and 5-Star Promise details"
      },
      {
        "url": "https://www.microtechboise.com/contact-us",
        "usedFor": "Verified business contact email and Garden City/Boise street address"
      },
      {
        "url": "https://www.microtechboise.com/submit_ticket",
        "usedFor": "Support ticket submission page inspection"
      },
      {
        "url": "https://www.microtechboise.com/ai-internal-security-solutions",
        "usedFor": "Evidence that MicroTech Systems already sells AI-driven monitoring, automated incident response, and custom AI integrations"
      },
      {
        "url": "https://www.microtechboise.com/blog/boise-managed-it-services-provider-leveraging-ai-for-faster-it-support",
        "usedFor": "Additional context on MicroTech's use of AI for alert prioritization, monitoring, and routine IT task automation"
      }
    ],
    "limitations": [
      "Employee headcount is not stated on the pages read.",
      "No owners, executives, or managers are formally identified by title on the company's About Us or Contact Us pages (names appear only inside customer testimonials, which are excluded under ForgeX rules).",
      "No service pricing is published on the website.",
      "Forms appear to be dynamically injected via script rather than static HTML form tags."
    ]
  },
  "qualification": {
    "category": "not a fit",
    "rationale": "MicroTech Systems is a B2B Managed IT Services Provider (MSP) and cybersecurity firm in Boise/Garden City, Idaho, rather than a home-service contractor in HVAC, plumbing, or electrical. Furthermore, MicroTech Systems already provides managed IT services, 24/7 automated monitoring, and custom AI security and automation solutions to its own business clients."
  }
}
